import java.nio.ByteBuffer;

public class MemoryDemonstrator {
    // Simulating a Direct Buffer memory leak pattern
    public static void leakDirectBuffer() {
        while (true) {
            // Allocates off-heap memory; ignores -Xmx limits
            ByteBuffer.allocateDirect(1024 * 1024 * 50); // 50MB chunks
        }
    }

    public static void main(String[] args) {
        try {
            leakDirectBuffer();
        } catch (OutOfMemoryError e) {
            System.err.println("Caught native OOM: " + e.getMessage());
            // System.exit or emergency cleanup routine
        }
    }
}
